window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["04"]={"https://www.gov.uk/foreign-travel-advice/argentina":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"34a833433bcc6051bd79b0dc0fd99819483756ca0893f10a29b97d422b68ddfe","read":"https://www.gov.uk/api/content/foreign-travel-advice/argentina","bytes":81129,"x":"fulltext v1","title":"Argentina travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-20T00:00:00+00:00","mod":"2026-05-07T17:26:11+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/argentina/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Argentina’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Argentina set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Argentine Consulate in the UK","https://clond.cancilleria.gob.ar/en"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Argentina, your passport must be valid for the proposed duration of your stay. If you are a resident in Argentina, your passport must be valid for entry."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Argentina without a visa for tourism for up to 90 days."]},{"k":"p","s":["To stay longer, or to work or study, you must meet the Argentine government’s entry requirements. Contact the ",["Argentine Consulate in the UK","https://clond.cancilleria.gob.ar/en"],"."]},{"k":"p","s":["Immigration authorities no longer stamp passports on entry. If you need proof of your entry or exit, contact the ",["Argentine Migration Office","https://www.migraciones.gov.ar/transitos/"]," (in Spanish)."]},{"k":"p","s":["If you wish to extend your stay for another 90-day period, get advice from the Argentine Migration Office before your current stay ends."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["If you’re travelling to Argentina for any purpose other than tourism, contact the ",["Argentine Consulate in the UK","https://clond.cancilleria.gob.ar/en"]," about the visas or permits you need and how to apply."]},{"k":"h","s":["Travelling with children"]},{"k":"p","s":["Children aged 17 and under who are resident in Argentina need written permission (‘Autorización de viaje’) from the non-accompanying parents to leave the country."]},{"k":"p","s":["Non-resident children aged 17 and under who have remained in Argentina for 1 year or more are treated in line with resident children and also need permission. You can get permission from a notary public in Argentina or the ",["Argentine Migration Office","https://www.argentina.gob.ar/interior/migraciones/autorizacion-de-salida-del-pais-de-ninos-ninas-y-adolescentes"]," (in Spanish)."]},{"k":"p","s":["You can get full information on the requirements from the ",["Argentine Migration Office","https://www.argentina.gob.ar/justicia/derechofacil/leysimple/salida-de-menores-al-extranjero"]," (in Spanish) or from your nearest ",["Argentine consulate","https://cancilleria.gob.ar/en/representaciones"],"."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Argentina guide","https://travelhealthpro.org.uk/country/11/argentina#Vaccine_Recommendations"],"."]},{"k":"p","s":["You may need a yellow fever certificate for onward travel to some other countries, due to the risk of yellow fever in Argentina."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Argentina","https://www.argentina.gob.ar/senasa/informacion-al-viajero/ingresar-o-regresar-al-pais"]," (in Spanish). You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into Argentina"]},{"k":"p","s":["You must ",["declare cash or travellers cheques worth more than 10,000 US dollars","https://www.afip.gob.ar/viajeros/ayuda/ingreso-egreso-de-valores.asp"]," (in Spanish)."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Argentina"]},{"k":"p","s":["Terrorist attacks in Argentina cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate including in places visited by foreign nationals. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"hs","s":["Political protests"]},{"k":"p","s":["Political demonstrations and picketing are more common in Argentina than in the UK. Some demonstrations attract large numbers of people, and they can occasionally turn violent. Demonstrations are particularly common near Congress (‘Congreso’) and the Presidential Palace (‘Casa Rosada’)."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid all protests, demonstrations and marches"]},{"k":"li","s":["exercise normal caution at any large gathering"]},{"k":"li","s":["be aware of your surroundings"]},{"k":"li","s":["monitor the local news"]},{"k":"li","s":["follow the advice of local authorities"]},{"k":"p","s":["There have also been occasional Falklands-related protests, including outside the British Embassy and British-affiliated businesses in Argentina."]},{"k":"hs","s":["Demonstrations"]},{"k":"p","s":["Groups of demonstrators (‘piqueteros’) sometimes block major roads at times of social unrest. These can include the major routes into and out of Buenos Aires City. This can cause significant delays."]},{"k":"p","s":["When planning to travel:"]},{"k":"li","s":["monitor the local news"]},{"k":"li","s":["do not attempt to cross blockades"]},{"k":"li","s":["follow the advice of local authorities"]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting your belongings"]},{"k":"p","s":["Thieves and pickpockets operate on public transport and at bus and train terminals."]},{"k":"p","s":["To reduce the risk of theft:"]},{"k":"li","s":["always keep a close eye on your personal possessions – do not hang bags on the back of seats"]},{"k":"li","s":["carry cash out of sight or close to you – a money belt under your clothes is the safest option"]},{"k":"li","s":["you may need to produce your passport when paying with a credit card, but keep a copy somewhere safe"]},{"k":"li","s":["keep your bags close while you are checking into a hotel or hostel – thieves posing as hotel guests can snatch them"]},{"k":"p","s":["Thefts from unattended vehicles, especially hire cars, are also common. This happens frequently in Bariloche, but can happen across the country."]},{"k":"hs","s":["Street crime and scams"]},{"k":"p","s":["In crowded places, thieves can cut handbags open. They can snatch a mobile phone while you are using it on the street. Thieves on motorbikes can snatch bags from pedestrians."]},{"k":"p","s":["Thieves – often women – use distraction techniques and may work in teams of 2 or more. A common form of distraction theft reported in Buenos Aires is the ‘mustard scam’. Thieves take your bags while an accomplice pretends to help you remove mustard they have sprayed on you. If this happens to you, politely but firmly refuse help and walk away."]},{"k":"p","s":["In Buenos Aires, be particularly cautious in:"]},{"k":"li","s":["Palermo"]},{"k":"li","s":["San Telmo Market and general area of San Telmo"]},{"k":"li","s":["La Boca"]},{"k":"li","s":["The Ecological Reserve"]},{"k":"li","s":["Retiro"]},{"k":"li","s":["Florida Street"]},{"k":"li","s":["9 de Julio"]},{"k":"li","s":["Avenida de Mayo"]},{"k":"li","s":["Avenida Rivadavia near the obelisk"]},{"k":"li","s":["Retiro Bus terminal"]},{"k":"li","s":["Cruise and ferry terminals"]},{"k":"p","s":["In Mendoza, be particularly cautious downtown."]},{"k":"p","s":["In Santa Fe, be particularly cautious in Rosario."]},{"k":"hs","s":["Violent crime"]},{"k":"p","s":["Armed robberies are a risk. If you are the victim of a robbery, hand over your cash and valuables without resistance."]},{"k":"p","s":["Be vigilant in La Boca, Buenos Aires, especially in the streets outside the Caminito tourist area. To reduce your risk, stay in the designated tourist area where there are high-visibility police patrols."]},{"k":"hs","s":["Criminal kidnapping"]},{"k":"p","s":["Kidnappings including ‘express kidnappings’ – short-term opportunistic abductions – occasionally happen in Argentina. Victims of express kidnap are held and forced to empty their bank accounts by making bank transfers or going to ATMs, after which they are normally quickly released. Be aware of your surroundings and always let someone you trust know your whereabouts. If you are a victim of kidnapping, follow the kidnapper’s instructions."]},{"k":"p","s":["To reduce your risk:"]},{"k":"li","s":["avoid wearing expensive clothing or jewellery, particularly in public"]},{"k":"li","s":["avoid casual taxis – see ",["Transport risks","https://www.gov.uk/foreign-travel-advice/argentina/safety-and-security#transport-risks"]]},{"k":"li","s":["be vigilant, especially at night"]},{"k":"hs","s":["Drink and food spiking and scams"]},{"k":"p","s":["Drinks and food can be spiked and could put you at risk of robbery or assault. Do not leave drinks unattended in bars and restaurants and do not accept food or drink from strangers."]},{"k":"p","s":["Be alert to the possible use of ‘date rape’ and other drugs. Alcohol and drugs can reduce your vigilance, making you less in control."]},{"k":"p","s":["There have been reports of foreign tourists being robbed or assaulted after inviting into their accommodation someone they have recently met, online or in person."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Do not become involved with illegal drugs of any kind. Possession of even very small quantities can lead to a lengthy prison sentence."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Argentine society is open and diverse. Discrimination based on sexual orientation is rare. Same-sex marriage is legal. Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Legal action against oil and gas companies"]},{"k":"p","s":["The government of Argentina has stated that it intends to pursue legal action against oil and gas companies engaged in hydrocarbon exploration in the Falkland Islands. If you’re travelling to Argentina and think you may be affected by this type of legal action, seek independent legal advice."]},{"k":"hs","s":["Surrogacy"]},{"k":"p","s":["Before you consider a surrogacy arrangement in Argentina, consider the challenges and risks involved, and make sure you seek specialist independent legal advice both in the UK and in Argentina. For more information, read FCDO guidance on ",["surrogacy overseas","https://www.gov.uk/government/publications/surrogacy-overseas"],"."]},{"k":"p","s":["Surrogacy is not regulated by law in Argentina and surrogacy arrangements are not enforceable in law."]},{"k":"p","s":["Local authorities may consider surrogacy arrangements to be illegal. Criminal investigations into surrogacy agencies and associated service providers are ongoing. Some intended parents have faced issues obtaining birth certificates and when attempting to leave Argentina with the child born to them through surrogacy."]},{"k":"p","s":["Children born through surrogacy in Argentina are Argentine citizens and must leave the country on an Argentine passport. They are also subject to local regulations applicable to the exit of minors in Argentina. See ",["Travelling with children","https://www.gov.uk/foreign-travel-advice/argentina/entry-requirements"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"p","s":["If you take part in extreme or adventure sports, including paragliding, climbing, off-road driving and hot air ballooning, make sure:"]},{"k":"li","s":["adequate safety precautions are in place"]},{"k":"li","s":["you only use reputable operators and insist on training"]},{"k":"li","s":["your travel insurance covers all the activities you want to undertake and includes helicopter rescue and medical evacuation"]},{"k":"p","s":["You will have to pay for most helicopter rescues, including in Mount Aconcagua."]},{"k":"p","s":["Altitude sickness is a risk when hiking in parts of Argentina. See ",["Health","https://www.gov.uk/foreign-travel-advice/argentina/health"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Argentina, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You’ll need to have both the ",["1949 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["Respect for speed limits and traffic signals varies. Drivers can make unexpected turns or brake suddenly."]},{"k":"p","s":["Vehicle crime is a problem. Always keep car windows closed and doors locked when driving in major cities."]},{"k":"p","s":["Take care when driving in the province of Misiones, close to the borders with Paraguay and Brazil. The area is used to smuggle goods. Seek local advice from customs officials if you intend to drive in this area."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Book taxis in advance if possible. If you hail a taxi in the street, only use a ‘radio taxi’. These have a clearly visible logo on the car doors."]},{"k":"p","s":["The Buenos Aries government has a ",["list of authorised radio taxi operators","https://data.buenosaires.gob.ar/dataset/transportes-autorizados-pasajeros"]," (in Spanish)."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["Flights from Argentina can be unreliable. Check for delays or cancellations before travelling to the airport."]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["Activist groups sometimes try to disrupt UK-flagged ships or commercial shipping working off the Falkland Islands. Contact the local authorities before travelling. Most cruise ships and visiting tourists should not be affected."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Many northern provinces experience occasional flooding. This can disrupt transport and could lead to shortages. Flash floods can occur during heavy rains, in provinces including Buenos Aires. Monitor local media and follow instructions given by the local authorities."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["There is a risk of earthquakes in Argentina, particularly in the provinces of Mendoza, San Juan, Salta and Jujuy. Monitor media reports and follow the advice of local authorities."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Volcanic eruptions"]},{"k":"p","s":["The Copahue Volcano on the Argentina-Chile border erupts occasionally, and the authorities will evacuate the area. If you’re travelling to this area, monitor local media reports and follow the advice of the local authorities."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["Wildfires can occur throughout Argentina and can spread rapidly. They may lead to road closures and affect the air quality in nearby areas."]},{"k":"p","s":["If you find yourself in or near the affected areas of any fire, monitor local media reports to stay informed of the rapidly evolving situation and follow the advice of the local authorities."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 107 or 911 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Argentina","https://travelhealthpro.org.uk/country/11/argentina#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Argentina","https://travelhealthpro.org.uk/country/11/argentina"],", including:"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["Zika virus"]},{"k":"li","s":["dengue"]},{"k":"p","s":["Altitude sickness is a risk in parts of Argentina. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Hantavirus"]},{"k":"p","s":["Hantavirus is present in Argentina. Read more information about ",["hantavirus in Argentina on TravelHealthPro.","https://travelhealthpro.org.uk/updates.php?base=5054"]," Further guidance on hantavirus is available from the ",["UK Health Security Agency","https://ukhsa.blog.gov.uk/2026/05/05/what-is-hantavirus-how-is-it-transmitted-and-what-are-the-symptoms/"]," and ",["Argentina’s Ministry of Health","https://www.argentina.gob.ar/salud/glosario/hantavirus"]," (website in Spanish)."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Argentina"]},{"k":"p","s":["Medical facilities are good but can be expensive. Public hospitals tend to be crowded."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Argentina","https://www.gov.uk/government/publications/argentina-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Argentina"]},{"k":"p","s":["Ambulance: 107"]},{"k":"p","s":["Fire: 100"]},{"k":"p","s":["Police: 911 or 101"]},{"k":"p","s":["To contact the emergency line (911) in Buenos Aires from outside Argentina call: +54 11 4309 9600, extensions 261099 or 261098"]},{"k":"h","s":["Police assistance"]},{"k":"hs","s":["Buenos Aires"]},{"k":"p","s":["For English-language safety tips or to file a police report online, go to ",["the Buenos Aires Police website","https://turistas.seguridadciudad.gob.ar/"]," (only accessible in Argentina)."]},{"k":"p","s":["Tourist Police (‘Comisaría del Turista’): +54 911 5050 9260 (24 hours)"]},{"k":"p","s":["Tourist Police WhatsApp: +54 911 5050 9260"]},{"k":"hs","s":["Mendoza"]},{"k":"p","s":["Tourist Police (‘Comisaría del Turista’): +54 261 413 2135 (24 hours)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO provides guidance on how to help yourself stay safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Argentina"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Argentina"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Argentina"]," in Argentina"]},{"k":"li","s":["dealing with a ",["death in Argentina","https://www.gov.uk/government/publications/argentina-bereavement-information/argentina-bereavement-infotmation"]]},{"k":"li","s":["being ",["arrested in Argentina","https://www.gov.uk/government/publications/argentina-prisoner-pack/argentina-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you are ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/argentina/british-embassy-buenos-aires"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/argentina/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Argentina","https://www.gov.uk/government/publications/overseas-business-risk-argentina"]," on how to manage political, economic, and business security-related risks."]}],"chars":17370,"change":"New information about Hantavirus in Argentina (‘Health’ page)."},"https://theconversation.com/blue-wave-the-democrats-historic-midterm-election-gains-could-also-offer-canada-a-path-to-peace-295834":{"r":"conversation","at":"2026-11-17T16:30Z","sha":"b178386655e03328f42ec1664fd151c9a7d8676098c6cfe155687781e80352b1","read":"https://theconversation.com/blue-wave-the-democrats-historic-midterm-election-gains-could-also-offer-canada-a-path-to-peace-295834","bytes":183957,"x":"fulltext v1","title":"Blue wave: The Democrats’ historic midterm election gains could also offer Canada a path to peace","by":[{"n":"Jason Opal","r":"Professor of History, The Ohio State University"}],"pub":"2026-11-04T16:30:24Z","mod":"","blocks":[{"k":"p","s":["During a ",["CBC Radio interview yesterday","https://www.cbc.ca/listen/live-radio/1-102-radio-noon-quebec/clip/16122602-trump-president-again.-what-thinking-about"],", I predicted a good night for the Democrats in the United States midterm elections — with the possibility of a great one."]},{"k":"p","s":["I was wrong."]},{"k":"p","s":["What happened was ",["the biggest rout of an incumbent party since 2006, when the Iraq War doomed George W. Bush’s Republican Party","https://www.npr.org/2026/11/04/nx-s1-6022532/how-this-years-midterms-stack-up-to-the-midterms-of-2006"],". It might turn out to be an even bigger win, especially in the semi-tropical conservative heartland known as the ",["Sun Belt","https://www.britannica.com/place/Sun-Belt"],", where the results seem like nothing less than a political revolution."]},{"k":"p","s":["For Canadians, this is likely good news — with Democrats now in control of both the House of Representatives and the Senate, the historical friendship between the U.S. and Canada may return to a firmer footing. In at least one Senate race — in Maine, where longtime Republican incumbent Susan Collins was defeated by Democrat Troy Jackson — ",["the Canada-U.S. trade war was a major campaign issue","https://www.cp24.com/news/money/2026/11/04/maine-elects-democratic-senator-after-race-that-featured-canada-us-trade-war/"],"."]},{"k":"p","s":["One former U.S. ambassador to Canada, Bruce Heyman, is already calling on Democrats to begin a reconciliation process with Canada."]},{"k":"h","s":["The landscape moves left"]},{"k":"p","s":["In terms of what happened stateside, let’s start with Ohio, where I’ve lived since moving here from Montréal shortly before the 2024 presidential election. Donald Trump won Ohio by 11 points that year. A hotly contested battleground in the early 2000s, the Buckeye State, ",["which has close economic ties with Canada","https://www.cbc.ca/news/world/in-ohio-canada-u-s-trade-war-sparks-anger-and-uncertainty-9.7324331"],", seemed safely Republican as recently as six months ago."]},{"k":"p","s":["But last night, all the usual Democratic voters, including younger people, professionals, racialized people and many low-wage workers, turned out in droves. Independents and moderates broke for the Democrats, and conservative voters showed far less enthusiasm for Republican candidates than they had for Trump."]},{"k":"p","s":["Take Lorain County, just west of Cleveland. A mostly white county of post-Second World War suburbs and poorer rural communities, ",["Lorain went for the Democratic candidate for Senate, Sherrod Brown, by 11 points","https://www.nytimes.com/interactive/2026/11/03/us/elections/results-ohio-us-senate-special.html"],", just two years after favouring Trump by six."]},{"k":"p","s":["Lorain broke for Dr. Amy Acton, the Democratic candidate for governor, by 14 percentage points — an extra jab, perhaps, at her Republican opponent, Trump acolyte ",["Vivek Ramaswamy, who had run a brutal ad that questioned Acton’s honesty","https://www.cbc.ca/news/world/ohio-controversial-campaign-ad-ramaswamy-acton-9.7389687"]," regarding the sexual abuse she suffered as a child."]},{"k":"p","s":["In other traditional battlegrounds like Michigan and in newer “purple” states like North Carolina, the same story played out."]},{"k":"p","s":["Democrats and independents flooded the polls, while Republicans stayed home or strayed from the party standard. Virtually every county shifted left relative to 2024, often by double digits, enabling the Democrats to take firm control of the U.S. Congress while also delivering governorships and state legislatures long held by Republicans."]},{"k":"p","s":["The wide and deep character of the vote indicates a holistic rejection of Trump’s MAGA movement and his policies over the past two years, including the tariff war with Canada and other allies, the Iran war and the immigration crackdown. Voters also registered their disapproval of Republican efforts to redraw electoral districts and of ",["Trump’s “let it ride” approach to AI development","https://www.scientificamerican.com/article/trump-rejects-ai-regulation-citing-parallels-with-climate-change-in-un-address/"],"."]},{"k":"h","s":["The Sun Belt"]},{"k":"p","s":["But the bigger story happened farther south, in states like South Carolina, Mississippi, Louisiana and, above all, Texas."]},{"k":"p","s":["This huge band of rural poverty and suburban comfort — the Sun Belt — was once the place where cotton was king. It was a vast domain for a ",["virulent strain of slavery","https://www.hup.harvard.edu/books/9780674975385"]," that emerged in the early 1800s and refused to remain in the same country as Abraham Lincoln and his “ ",["Black Republicans","https://nkaa.uky.edu/nkaa/items/show/2044"],"” (the Republicans, founded in the mid-1850s, included abolitionists and pledged to contain slavery)."]},{"k":"p","s":["After the Civil Rights movement of the 1950s and ‘60s, these states shifted dramatically to the right, embracing the Republicans as the party of small government, evangelical piety and proud patriotism. Mostly white Republicans have simply overwhelmed the majority Black and Democratic strongholds of their states."]},{"k":"p","s":["In 2026, however, historically Black counties in places like the Mississippi Delta turned out in such huge numbers that the weakened Republican vote could no longer hold."]},{"k":"p","s":["As of this writing, the Democratic candidate for U.S. Senate, Scott Colom, is leading the incumbent Republican by ",["43 votes","https://www.nytimes.com/interactive/2026/11/03/us/elections/results-mississippi-us-senate.html"]," out of nearly 950,000 cast."]},{"k":"p","s":["And then there is the biggest prize of all: Texas, one of only a handful of U.S. states that was once an independent republic, in this case a slaveholders’ cotton-growing frontier called the Lone Star Republic (1836-46)."]},{"k":"p","s":["Home to more than 31 million people, Texas is not shy about being Texas. (My grandfather, a Second World War veteran, proudly told me that he once got into a fist fight with his Texas-born superior when that officer tried to make my grandfather stand and sing, “The Yellow Rose of Texas.”)"]},{"k":"p","s":[["Around 40 per cent","https://www.texastribune.org/2023/06/21/census-texas-hispanic-population-demographics/"]," of Texans are Spanish-speaking voters who generally prefer Democrats but who had veered towards Trump two years ago."]},{"k":"p","s":["They veered back."]},{"k":"p","s":["For example, Webb County — on the border with Mexico — had gone to Trump in 2024 by two points. Last night, the Democratic candidate for U.S. Senate, James Talarico, won it by ",["47 points","https://www.nytimes.com/interactive/2026/11/03/us/elections/results-texas-us-senate.html"],"."]},{"k":"p","s":["I repeat: A county moved nearly 50 points in two years."]},{"k":"h","s":["What’s ahead?"]},{"k":"p","s":["What happens now depends on whether the Democrats can consolidate last night’s mighty alliance of moderates, young people, racialized people, professionals and lower wage earners."]},{"k":"p","s":["To do so, they will have to drop their occasional aversion to piety in public life (Talarico is a devout Presbyterian who gave his ",["victory speech","https://www.pbs.org/newshour/politics/watch-live-democrat-james-talarico-speaks-after-winning-texas-senate-seat"]," in front of the words “Love Thy Neighbor.”)"]},{"k":"p","s":["They will need to address economic problems. They will need to be disciplined."]},{"k":"p","s":["If they can do so, then the entire political map of the U.S. will be transformed, with the Sun Belt coloured purple and the Democratic Party capable of the kind of ",["sustained dominance we haven’t seen since Ronald Reagan’s Republicans in the 1980s","https://americanarchive.org/primary_source_sets/conservatism"],"."]},{"k":"p","s":["As Canadians have learned over the last two years, and more broadly over the last two centuries, America can always surprise you."]}],"chars":6002},"https://www.gov.uk/foreign-travel-advice/cote-d-ivoire":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"6afa81647505606b22ba8896b3457c2fea566507a44fc5de4ce13b47cd7c191b","read":"https://www.gov.uk/api/content/foreign-travel-advice/cote-d-ivoire","bytes":58822,"x":"fulltext v1","title":"Côte d'Ivoire travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-22T00:00:00+00:00","mod":"2026-11-09T16:16:31+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Borders with Burkina Faso and Mali"]},{"k":"p","s":["FCDO advises against all travel to:"]},{"k":"li","s":["within 40km of the borders with Burkina Faso and Mali"]},{"k":"li","s":["Northern Zanzan and Savanes provinces"]},{"k":"li","s":["Comoé National Park"]},{"k":"p","s":["This is due to an increased risk of terrorist attacks and kidnaps by terrorists based in the Sahel region, which includes Burkina Faso and Mali."]},{"k":"hs","s":["Côte d’Ivoire-Liberia border"]},{"k":"p","s":["FCDO advises against all but essential travel to within 20km of the border with Liberia owing to the risk of serious violence by local militias."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/regional-risks"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Côte d’Ivoire’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Côte d’Ivoire set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Embassy of Côte d’Ivoire in the UK","https://royaumeuni.diplomatie.gouv.ci/contacts.php?lang=en"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Côte d’Ivoire, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to enter Côte d’Ivoire."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":[["Apply and pay for an e-visa online","https://snedai.com/e-visa/"]," at least 10 working days before you travel to allow time for your application to be processed. Once it is approved, you will be able to collect your visa on arrival at Abidjan airport."]},{"k":"p","s":["If you are not an Economic Community of West African States (ECOWAS) national, you must hold a valid visa or have had your application for an e-visa approved before you travel."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Côte d’Ivoire, you must have a certificate to prove you’ve had a yellow fever vaccination."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Côte d’Ivoire guide","https://travelhealthpro.org.uk/country/112/cte-divoire-ivory-coast#Vaccine_Recommendations"],"."]},{"k":"h","s":["Ebola screening and health declaration"]},{"k":"p","s":["As a public health measure, Côte d’Ivoire has introduced screening for travellers arriving from countries affected by the Ebola outbreak. The World Health Organisation (WHO) has ",["declared this a Public Health Emergency of International Concern","https://www.who.int/news/item/17-05-2026-epidemic-of-ebola-disease-in-the-democratic-republic-of-the-congo-and-uganda-determined-a-public-health-emergency-of-international-concern"]]},{"k":"p","s":["If you are travelling to or through Côte d’Ivoire from another African country, you must complete an online health declaration on the ",["Destination Côte d’Ivoire website","https://destinationci.com/"]," before you arrive. The QR code generated by the form must be shown on arrival."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Côte d’Ivoire","https://www.douanes.ci/particulier/voyageurs-nationaux-et-non-nationaux"]," (in French). You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into Côte d’Ivoire"]},{"k":"p","s":["You can take up to 500,000 West African CFA francs in cash into Côte d’Ivoire. You must declare any foreign currency."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Côte d’Ivoire","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Côte d’Ivoire"]},{"k":"p","s":["Terrorist attacks in Côte d’Ivoire cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate, including in places visited by foreign nationals such as:"]},{"k":"li","s":["beach resorts"]},{"k":"li","s":["hotels"]},{"k":"li","s":["cafés and restaurants"]},{"k":"li","s":["major sporting events"]},{"k":"p","s":["The main threat in Côte d’Ivoire is from Jama’at Nusrat al-Islam wal-Muslimin (JNIM) and other al-Qa’ida (AQ) affiliated groups, including al-Qa’ida in the Islamic Maghreb (AQIM). JNIM is mainly active in the northern border areas, including the Comoé National Park in the north-east, but attacks could occur anywhere, including major towns and cities such as Abidjan."]},{"k":"p","s":["Stay aware of your surroundings, keep up to date with local media reports and follow the advice of the local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Political demonstrations sometimes take place in Abidjan and regional towns, particularly around elections. The authorities may use tear gas to disrupt unauthorised protests. Crowds can gather quickly, and roadblocks are common. It is possible that, in the event of significant unrest, internet access might be restricted."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid crowds and demonstrations"]},{"k":"li","s":["follow local instructions and any additional security checks or measures"]},{"k":"li","s":["monitor local media"]},{"k":"p","s":["Be alert near military barracks and military installations."]},{"k":"h","s":["Personal security measures"]},{"k":"p","s":["If you’re staying for long in Côte d’Ivoire, you should seek professional security advice and regularly review personal security arrangements. You should keep a stock of food and water."]},{"k":"h","s":["Crime"]},{"k":"p","s":["There is a risk of violent crime in Abidjan, including armed break-ins to private residences and armed hold-ups in the street. Though not common, they do occur."]},{"k":"hs","s":["Street crime"]},{"k":"p","s":["To reduce your personal risk:"]},{"k":"li","s":["use taxi apps or pre-arranged private taxis"]},{"k":"li","s":["avoid using public transport after dark"]},{"k":"li","s":["make sure your accommodation has security measures in place"]},{"k":"li","s":["keep any valuables out of sight and do not wear expensive-looking jewellery or watches"]},{"k":"li","s":["do not walk after dark"]},{"k":"li","s":["take transport to use ATMs or to exchange money at the bank"]},{"k":"p","s":["To prevent card fraud, keep your bank card in sight when paying bills."]},{"k":"hs","s":["Vehicle crime"]},{"k":"p","s":["There have been attacks by armed robbers on private cars driving on the main roads in the west of the country. You could be at risk in daylight as well as at night."]},{"k":"p","s":["Keep your car doors locked, windows shut and all valuables out of sight while driving."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["You must carry your passport. Carry the original as the police will not always accept copies."]},{"k":"hs","s":["Dress code"]},{"k":"p","s":["Dress modestly when visiting religious places or buildings."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Drug trafficking and possession are illegal. If you’re found guilty, you could receive a long prison sentence or a heavy fine."]},{"k":"hs","s":["Using cameras in secure areas"]},{"k":"p","s":["It is prohibited to take photographs near sensitive installations, including:"]},{"k":"li","s":["military sites"]},{"k":"li","s":["government buildings"]},{"k":"li","s":["radio and TV stations"]},{"k":"li","s":["the Presidency building"]},{"k":"li","s":["Abidjan Airport"]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is not illegal in Côte d’Ivoire, but the law does not recognise same-sex partnerships or marriage. Attitudes are less tolerant and there is no specific anti-discrimination law to protect LGBT+ people."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Côte d’Ivoire, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You must have the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," or a local driving licence. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["In case the police stop you, always carry your UK licence and an IDP, or a local licence, plus your car registration documents and insurance card."]},{"k":"p","s":["If you want to apply for a local driving licence, get your UK driving licence ",["authenticated by the DVLA","https://www.gov.uk/view-driving-licence"]," in the UK."]},{"k":"hs","s":["Road conditions"]},{"k":"p","s":["Driving standards in Côte d’Ivoire are poor. There is a high number of fatal road accidents and emergency services outside of Abidjan are unreliable."]},{"k":"p","s":["Road conditions are improving in Abidjan, but driving outside the capital is much more difficult. Poorly lit roads and the risk of stray livestock make driving particularly dangerous at night. During the rainy season minor roads may become impassable."]},{"k":"hs","s":["Public transport"]},{"k":"p","s":["Take care when using public transport – driving standards and vehicle maintenance are poor."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Taxis, including share taxis, operate in Abidjan and other cities in Côte d’Ivoire. Vehicles used as taxis tend to be old and there may be issues with the standard of maintenance. Ride-hailing apps are also available, and vehicles operating on these apps tend to be better maintained. Although no taxi can be guaranteed safe, we recommend using ride-hailing apps where possible."]},{"k":"hs","s":["Roadblocks and checkpoints"]},{"k":"p","s":["There are roadblocks and checkpoints in and around Abidjan and across the country. The Côte d’Ivoire government is currently running a campaign against bad driving and unroadworthy vehicles."]},{"k":"p","s":["Slow down at any type of checkpoint and stay calm. Comply when the police ask you for routine paperwork such as photo ID, driving licence, insurance and vehicle registration or ownership documents, which you should carry with you in your vehicle."]},{"k":"p","s":["Beware of unofficial roadblocks – you could be robbed or assaulted. These are sometimes set up by armed bandits known as ‘coupeurs de route’ and are mostly on secondary or quiet roads."]},{"k":"p","s":["If the police issue you with a fine, they should also issue you with related paperwork."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["The rainy season is between May and November. Torrential rains often cause flooding, landslides and large potholes. Flash flooding has caused deaths. Monitor local weather reports."]},{"k":"hs","s":["Ocean currents"]},{"k":"p","s":["Ocean currents are very strong along the coast. Rip tides cause many swimming accidents and drownings each year. There is no lifeboat or rescue service."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Côte d’Ivoire. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire"],"."]},{"k":"h","s":["Borders with Burkina Faso and Mali"]},{"k":"p","s":["FCDO advises against all travel to within 40km of the borders with Burkina Faso and Mali. There is an increased risk of terrorist attacks and kidnaps by terrorists based in the Sahel region, which includes Burkina Faso and Mali."]},{"k":"h","s":["Northern provinces"]},{"k":"p","s":["FCDO also advises against all travel to:"]},{"k":"li","s":["Northern Zanzan and Savanes provinces"]},{"k":"li","s":["Comoé National Park"]},{"k":"p","s":["See ",["Safety and security","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/safety-and-security"]," for details about terrorism risks in Côte d’Ivoire."]},{"k":"h","s":["Côte d’Ivoire-Liberia border"]},{"k":"p","s":["FCDO advises against all but essential travel to within 20km of the border with Liberia. This is due to the risk of clashes between local militias and security forces. Fatal clashes have taken place in and around this area in the past. If you travel to this area, seek professional security advice locally."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 185 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Côte d’Ivoire","https://travelhealthpro.org.uk/country/112/cote-divoire-ivory-coast#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Côte d’Ivoire","https://travelhealthpro.org.uk/country/112/cote-divoire-ivory-coast"],", including:"]},{"k":"li","s":["Zika virus"]},{"k":"li","s":["malaria and dengue"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["Ebola virus"]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Côte d’Ivoire"]},{"k":"p","s":["Medical facilities in Abidjan are of a reasonable standard but can be expensive. Emergency facilities are limited to a few major hospitals. Outside of Abidjan medical facilities are rudimentary."]},{"k":"p","s":["Serious medical treatment could require medical evacuation back to the UK. Make sure you have adequate travel health insurance and funds to cover the cost of any medical treatment and repatriation."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Côte d’Ivoire","https://www.gov.uk/government/publications/cote-divoire-list-of-medical-facilitiespractitioners/cote-divoire-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Côte d’Ivoire"]},{"k":"p","s":["Ambulance: 185"]},{"k":"p","s":["Fire: 180"]},{"k":"p","s":["Police: 110, 111 or 170"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=C%C3%B4te%20d%27Ivoire"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=C%C3%B4te%20d%27Ivoire"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=C%C3%B4te%20d%27Ivoire"]," in Côte d’Ivoire"]},{"k":"li","s":["dealing with a ",["death in Côte d’Ivoire","https://www.gov.uk/government/publications/cote-divoire-bereavement-death-abroad"]]},{"k":"li","s":["Being ",["arrested or imprisoned in Côte d’Ivoire","https://www.gov.uk/government/publications/cote-divoire-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/cote-d-ivoire/british-embassy-abidjan"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Côte d’Ivoire","https://www.gov.uk/government/publications/overseas-business-risk-cote-divoire"]," on how to manage political, economic, and business security-related risks."]}],"chars":15030,"change":"New information about Ebola screening and health declarations when arriving in country (‘Entry requirements’ page)."},"https://theconversation.com/nvidia-jensen-huang-and-the-history-of-sexpionage-296187":{"r":"conversation","at":"2026-11-17T16:30Z","sha":"aa49453161effce2d3bf03fe94f372a23ac46aa425c88c7c3f2a49ba3147f8b8","read":"https://theconversation.com/nvidia-jensen-huang-and-the-history-of-sexpionage-296187","bytes":183735,"x":"fulltext v1","title":"Nvidia, Jensen Huang and the history of ‘sexpionage’","by":[{"n":"Robert Dover","r":"Professor of Intelligence and National Security & Dean of Faculty, University of Hull"}],"pub":"2026-11-11T12:02:33Z","mod":"","blocks":[{"k":"p","s":["A large portion of intelligence work is focused on collecting information your competitor or adversary does not want you to have. But another key focus of intelligence is on compromising key individuals."]},{"k":"p","s":["This involves damaging reputations or putting people in a position where they might disclose sensitive information. To achieve that, ",["intelligence","https://theconversation.com/topics/spying-1616"]," agencies have often used the suggestion, promise or reality of sex."]},{"k":"p","s":["The reemergence of interest in ",["“sexpionage”","https://www.independent.co.uk/news/world/politics/how-russia-still-trying-to-use-sex-for-spying-a7529221.html"]," comes from recent ",["allegations","https://www.nytimes.com/2026/11/08/technology/nvidia-investigation-jensen-huang.html"]," around Nvidia CEO Jensen Huang and ",["his relationship with","https://www.ft.com/content/a55a2a22-4479-4f93-a445-6147a5c6d790?syn-25a6b1a6=1"]," an executive of a ",["partner company","https://www.nytimes.com/2025/10/09/technology/nvidia-chips-china-megaspeed.html"],". The US intelligence community ",["believes","https://www.nytimes.com/2026/11/09/business/jensen-huang-china-spying.html"]," the woman in question, Alice Huang, is connected to Chinese intelligence."]},{"k":"p","s":[["Nvidia","https://theconversation.com/why-is-nvidia-so-powerful-in-the-ai-world-and-what-could-jensen-huangs-scandal-really-cost-296257"],", the computing power behind American AI advances and a ",["significant financial factor","https://www.reuters.com/business/media-telecom/no-ordinary-ceo-why-ai-race-cannot-do-without-nvidias-jensen-huang-2026-11-09/"]," in US stock market gains, has launched its own investigation. And the US president, Donald Trump, has ",["said the FBI","https://www.bbc.co.uk/news/articles/cqg7x7dpvym8o"]," is looking into the situation. China has ",["dismissed the claims","https://www.nytimes.com/2026/11/09/business/jensen-huang-china-spying.html"]," as a groundless smear campaign."]},{"k":"p","s":["The situation has drawn attention to the wider vulnerabilities the west has to spying. The key question is: does any western organisation with deep exposure to Chinese partners have a realistic understanding of how information moves out of those relationships?"]},{"k":"p","s":["My assessment is they do not. In part, this is because Chinese intelligence is widely viewed as a mirror of the west’s heavily controlled intelligence agencies."]},{"k":"p","s":["But China’s 2017 ",["National Intelligence Law","https://www.chinalawtranslate.com/en/national-intelligence-law-of-the-p-r-c-2017/"]," requires organisations and citizens to support and cooperate with state intelligence work. Any partner with meaningful ties to China is thus a potential conduit, regardless of whether they have been formally recruited."]},{"k":"h","s":["‘Honeytrap’ agents"]},{"k":"p","s":["Sexpionage captures headlines and drags eyeballs. The promise of a fallen man (nearly always a man) has been a staple of tabloid newspapers, novels, films and television for well over a century. Among the most prominent examples is ",["the Profumo Scandal","https://www.tandfonline.com/doi/full/10.1080/13619462.2016.1261698"]," in the 1960s."]},{"k":"p","s":["At that time, the then-UK secretary for war, John Profumo, ",["had an affair","https://blogs.bodleian.ox.ac.uk/archivesandmanuscripts/2013/03/22/50-years-ago-the-profumo-affair/"]," with a 19-year-old woman, who was also intimate with a Soviet defence attache. This created an intelligence vulnerability. Similarly, ",["suggestions","https://theconversation.com/a-whiff-of-espionage-around-the-epstein-files-points-to-how-intelligence-and-influence-interact-275344"]," of government connections to the dead and disgraced financier Jeffrey Epstein provide whiffs of espionage to sexual abuse and compromise."]},{"k":"p","s":["Read more: ",["A whiff of espionage around the Epstein files points to how intelligence and influence interact","https://theconversation.com/a-whiff-of-espionage-around-the-epstein-files-points-to-how-intelligence-and-influence-interact-275344"]]},{"k":"p","s":["Sexpionage can even be seen in biblical accounts. The Book of Joshua tells the story of a woman called Rahab who ",["used her access","https://engelsbergideas.com/portraits/rahab-the-old-testaments-female-super-spy/"]," to Jericho’s military leaders to pass on secrets to the Israelites. It also featured in the intrigues of the middle ages and prominently in the first world war."]},{"k":"p","s":[["Mata Hari","https://www.theguardian.com/lifeandstyle/2016/dec/05/the-real-mata-hari-executed-abused-woman"],", a Dutch dancer and spy, was executed in 1917 having promised intelligence to both the French and German militaries. These intrigues were based on her entanglements with senior military officials on both sides."]},{"k":"p","s":["Later, during the cold war, the Soviets and East Germans refined their use of so-called “honeytrap” agents towards using ordinary looking, reasonably well-educated men and women with whom a relationship ",["would look believable","https://archive.org/details/spymastermythirt0000kalu"],". These relationships often began without coercion and consequently the betrayal of secrets was more enduring and deniable."]},{"k":"p","s":["A large number of western officials were recalled home from Moscow or Soviet satellite states during this period after being caught in compromising and staged situations with Russian agents. There were some, like ",["British civil servant John Vassall","https://www.politics.co.uk/history/admiralty-clerk-john-vassall-arrested-for-spying/"],", whose compromised status was not detected and who spied for the Soviet Union."]},{"k":"p","s":["Intelligence agencies also had conspicuous success during the cold war through the exploitation of closeted gay men like Vassall and the Canadian ambassador to Moscow, ",["John Watkins","https://www.upi.com/Archives/1982/01/06/John-Watkins-acted-like-a-man-with-little-time/4355379141200/"],", whose compromise might see them prosecuted if they did not comply."]},{"k":"p","s":["According to author Henry Schlesinger, the purpose of sexpionage falls ",["into four categories","https://uk.bookshop.org/p/books/honey-trapped-sex-betrayal-and-weaponized-love-henry-r-schlesinger/8a4ad38b044620b4"],". First is to control or coerce the target, persuading them to spy. Second is to collect “pillow talk”, the injudicious comments to a lover in an intimate moment and giving access to their phones or computers."]},{"k":"p","s":["The third category is collecting information that allows for further exploitation of the target. Minor legal snags such as recreational drug use or driving infringements can be leveraged further. And the fourth is collecting a means by which to discredit protest or political movements."]},{"k":"p","s":["This is essentially the subject of the current ",["Undercover Policing Inquiry","https://www.ucpi.org.uk/"]," in the UK. Evidence to the inquiry by the Metropolitan Police has confirmed that ",["undercover police officers","https://www.theguardian.com/uk/2013/mar/01/spy-mark-kennedy-number-relations"]," engaged in sexual relationships to collect intelligence and ",["undermine protest groups","https://www.theguardian.com/uk-news/2024/dec/08/undercover-officer-denies-role-in-arson-attack-on-debenhams-in-1987"]," from the 1970s until at least 2011."]},{"k":"h","s":["Targeting tech executives"]},{"k":"p","s":["If we bring sexpionage to the modern day, what might an intelligence agency or officer be considering when targeting a technology executive?"]},{"k":"p","s":["Receiving forewarning of US government decisions is a key interest for China, as is gauging the extent to which the US tech industry relies on Taiwan. Moreover, access to technology or finance executives and companies is valuable."]},{"k":"p","s":["We also need to consider the incentives of technology leaders. Private firms are not obliged to engage in ",["counterintelligence","https://www.fbi.gov/investigate/counterintelligence"],", the business of finding spies. Stopping a major commercial partnership because there is some evidence of exposure to a foreign government could also be seen as bad business."]},{"k":"p","s":["However, businesses should have some curiosity in who they are trading with, not least because of the ",["strong market responses","https://www.theguardian.com/business/live/2026/nov/09/nvidia-jensen-huang-scandal-investigation-ai-industry-tech-stocks-recovery-slump-latest-news-updates"]," to this. Nvidia’s share price ",["tumbled","https://www.nytimes.com/2026/11/09/business/nvidia-stock-price-jensen-huang-ceo.html"]," US$330 billion (£246 billion) after the company announced it would launch an investigation into the recent reports."]},{"k":"p","s":["Governments need to watch closely for compromise activities against companies they now think of as ",["core infrastructure","https://link.springer.com/article/10.1007/s41125-026-00120-z"],". In the Nvidia case, it has been ",["reported","https://www.nytimes.com/2026/11/08/us/politics/rubio-nvidia-ceo-chinese-spy.html"]," that US government officials suspected there was a problem before allowing the company’s ",["advanced H200 chips","https://en.sedaily.com/international/2026/11/08/nvidias-huang-faces-scrutiny-over-h200-china-sales-alleged"]," to be exported to China."]},{"k":"p","s":["This is the sort of vulnerability intelligence agencies are there to prevent."]}],"chars":6083},"https://www.gov.uk/foreign-travel-advice/czechia":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"66780923ccc64cb210ead3defc358a4c3ce627c34cab41cf3027922e1fa27026","read":"https://www.gov.uk/api/content/foreign-travel-advice/czechia","bytes":79556,"x":"fulltext v1","title":"Czechia travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-20T00:00:00+00:00","mod":"2026-08-11T10:18:36+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/czech-republic/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Czechia set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Czech Embassy in the UK","https://www.mzv.cz/london"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Czechia follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it might have a date of issue that is more than 10 years ago, making it invalid for entry to the Schengen area"]},{"k":"li","s":["have an ‘expiry date’ at least 3 months after the day you plan to leave the Schengen area (the expiry date does not need to be within 10 years of the date of issue)"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can travel without a visa to the Schengen area, which includes Czechia, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["The requirements for ",["working in Czechia","https://www.gov.uk/guidance/travel-to-the-czech-republic-for-work"]," are different."]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days. If you overstay the 90-day visa-free limit, you may be banned from entering Schengen countries for up to 3 years."]},{"k":"p","s":["At Czech border control, you may also need to:"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"li","s":["prove that you have enough money for your stay – the amount varies depending on your accommodation"]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer, you must meet the Czech government’s entry requirements. Check which type of visa or permit you need with the ",["Czech Embassy in the UK","https://mzv.gov.cz/london/en/visa_and_consular_information/visa_information/index.html"],"."]},{"k":"p","s":["If you stay in Czechia with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit."]},{"k":"p","s":["Read about ",["entry processes if you live in Czechia","https://www.gov.uk/guidance/living-in-the-czech-republic#passports-and-travel"],"."]},{"k":"h","s":["New Schengen entry requirements"]},{"k":"p","s":["The European Union’s (EU) new Entry/Exit System (EES) is now being implemented across the Schengen area."]},{"k":"p","s":["This means that when you travel into the Schengen area for short stays, you may need to register your biometric details, such as fingerprints and a photo. There is no cost for EES registration."]},{"k":"p","s":["On your first visit into a Schengen country, you may be asked to register your details at a special booth before proceeding to the immigration desk. Follow directions from your travel operator or the staff at your port of entry. You may also need to provide either your fingerprint or photo when you leave the Schengen area. Children aged 11 or younger will not have their fingerprints scanned but can be required to have their photo taken."]},{"k":"p","s":["You do not need to take any action before you arrive at the border on entry to the Schengen area, but EES may take each passenger extra time to complete so be prepared to wait longer than usual at the border and to allow more time for immigration controls when you depart the Schengen area. If you are departing the Schengen area by plane, allow extra time to reach your departure gate as EES checks may take place before boarding."]},{"k":"p","s":["EES is replacing the previous system of manually stamping passports when visitors arrive in the Schengen area for short stays. You may be asked to input biometric details every time you enter or exit."]},{"k":"p","s":["If you enter the Schengen area through the Port of Dover, Eurotunnel at Folkestone or Eurostar at St Pancras International, any information will be taken at the border before you leave the UK."]},{"k":"p","s":["Your digital EES record is valid for 3 years."]},{"k":"p","s":["Read more ",["information on the EU Entry/Exit System and to understand which countries are in the Schengen area","https://www.gov.uk/guidance/eu-entryexit-system"],"."]},{"k":"p","s":["If you are long-term resident in a Schengen country, you are exempt from EES in all Schengen countries. The full list of EES exemptions is on ",["the EU’s official Travel Europe website.","https://travel-europe.europa.eu/en/ees/to-whom-does-ees-not-apply"]]},{"k":"p","s":["If you believe you have been incorrectly entered into EES or your record of time spent in the Schengen area is incorrect, approach border officials when you next cross the Schengen border and request a correction. If you are exempt, carry documentation confirming your status. If you believe your time spent in the Schengen area has been recorded incorrectly, raise this with border officials and be prepared to provide supporting evidence if requested."]},{"k":"h","s":["Border controls at Germany’s land borders"]},{"k":"p","s":["There are temporary border controls in place to travel into Germany. Check the ",["entry requirements for Germany","https://www.gov.uk/foreign-travel-advice/germany/entry-requirements"],"."]},{"k":"h","s":["Registering with the police"]},{"k":"p","s":["If you do not have a Czech residence permit, you must register your address with the ",["nearest foreign police department","https://www.policie.cz/clanek/oddeleni-pobytovych-agend.aspx"]," (in Czech) within 3 days of arriving. You can also register through your hotel or accommodation service. If you do not register, you could get a fine of up to 3,000 Czech koruna."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods that can be brought into and taken out of Czechia","https://www.celnisprava.cz/en/clo/informace-pro-fyzicke-osoby/Pages/information-of-the-customs-administration-of-the-czech-republic-for-travellers-regarding-modifications-as-regards-imports-o.aspx"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking food into Czechia"]},{"k":"p","s":["You cannot take ",["meat, milk or products containing them into EU countries","https://food.ec.europa.eu/animals/animal-products-movements/personal-imports_en"],". There are some exceptions such as powdered baby milk, baby food and special foods or pet feed required for medical reasons."]},{"k":"hs","s":["Taking money into or out of Czechia"]},{"k":"p","s":["Declare cash or travellers cheques if the value is 10,000 euros or more. You will get a certified declaration to show you brought it in with you. If you do not, your money could be seized when you leave. For more information, see ",["import and export of financial funds","https://www.celnisprava.cz/en/dalsi-kompetence/informace-pro-fyzicke-osoby/Pages/import-and-export-of-financial-funds.aspx"],"."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Czechia"]},{"k":"p","s":["Terrorist attacks in Czechia cannot be ruled out."]},{"k":"p","s":["You should be aware of the global risk of indiscriminate terrorist attacks which could be in public places, including in places frequented by expatriates and foreign travellers."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Public protests may happen at short notice. These have been peaceful but take care in crowded places and follow the instructions of local authorities."]},{"k":"h","s":["Crime"]},{"k":"p","s":["If you are victim of crime, immediately call 112 for assistance."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Petty theft is a problem, especially in major tourist areas in Prague. There is a risk of pickpocketing:"]},{"k":"li","s":["on busy metro and bus routes from Prague airport to the city centre"]},{"k":"li","s":["on trams to popular tourist sites like Prague Castle"]},{"k":"li","s":["in busy tourist areas"]},{"k":"p","s":["Take care of yourself and your belongings in the same way as you would do in the UK. Avoid leaving your belongings unattended."]},{"k":"p","s":["Report thefts in person to the nearest Czech police station within 24 hours and get a police report crime number for insurance purposes."]},{"k":"p","s":["Prague police station (Jungmannovo namesti 9, Prague 1, nearest metro stop is Mustek) is open 24 hours a day and would provide English speaking interpreters."]},{"k":"p","s":["You can also get a police report from the police station at the airport. See ",["Prague police station contact details","https://www.policie.cz/SCRIPT/imapa.aspx?area=pha&docid=672&nid=269&num=1"]," (in Czech)."]},{"k":"p","s":["Every lamppost in Prague has a 6-digit number posted at eye level. These codes will help you tell the police where you are if you cannot give them an exact address."]},{"k":"hs","s":["Drink spiking"]},{"k":"p","s":["There is a risk of drink spiking in bars and clubs. Be careful not to take drinks from strangers or leave your drinks unattended."]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Beware of criminals pretending to be plainclothes policemen who ask to see your foreign currency and passport. Czech police officers do not have the right to do this. Do not show them your money. Instead, offer to go with them to the nearest police station. You can also call 112 to check their identity."]},{"k":"h","s":["Travelling in groups"]},{"k":"p","s":["If you’re travelling in a group, keep a note of your hotel phone number and address in case you are separated. Leave contact details with a friend or relative in the UK."]},{"k":"h","s":["Prague safety issues"]},{"k":"p","s":["Prague city police advise visitors to:"]},{"k":"li","s":["always change money at a currency exchange or bank rather than on the street as this money is often counterfeit"]},{"k":"li","s":["take care when using cash machines"]},{"k":"li","s":["avoid contact with sex workers"]},{"k":"li","s":["be aware of consumption charges in night clubs as they are often high"]},{"k":"li","s":["be careful with consumption cards, which carry high financial penalties if you lose them before you pay your bill"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["It is a legal requirement to carry ID. Always carry your passport. The police may fine or arrest you if you do not. They will normally accept a scan of your passport if you have not committed a crime."]},{"k":"hs","s":["Drunken and offensive behaviour"]},{"k":"p","s":["Stag groups are not allowed to enter some city centre bars and restaurants. You may be arrested or fined for drunken or offensive behaviour. Police may take you to ‘sober-up’ facilities for a temporary period, and you will have to pay for your stay."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["The possession, sale and distribution of drugs, including cannabis, is illegal, and the drugs are often dangerous counterfeits. Some shops, particularly in Prague, advertise ‘cannabis products’, which contain trace amounts of THC permissible under Czech law."]},{"k":"p","s":["You should expect severe penalties such as a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport. Convictions carry sentences of up to 18 years."]},{"k":"p","s":["Airports in Czechia have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex relationships and civil partnerships are legal in Czechia, but same-sex marriages are not recognised in Czech law. Registered same-sex partnerships are awaiting presidential approval. Same-sex couples showing affection in public could receive unwanted attention. Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Surrogacy"]},{"k":"p","s":["It is illegal to earn money from a surrogacy arrangement."]},{"k":"p","s":["The police may charge you if you are:"]},{"k":"li","s":["a surrogate mother"]},{"k":"li","s":["a British national who plans to take a child born through surrogacy"]},{"k":"li","s":["an agent organising the handover"]},{"k":"p","s":["FCDO advises against making surrogacy arrangements in Czechia or moving surrogacy arrangements from other countries."]},{"k":"p","s":["You should get specialist legal advice in the UK and Czechia. See ",["surrogacy arrangements in foreign countries","https://www.gov.uk/government/publications/surrogacy-overseas/surrogacy-overseas"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Czechia, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s Czechia guide","https://www.rac.co.uk/drive/travel/country/czech-republic/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Czechia. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the correct version of the ",["international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP."]},{"k":"p","s":["Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],"."]},{"k":"p","s":["If you are visiting Czechia, you may be able to use your ",["Blue Badge","https://www.gov.uk/government/publications/blue-badge-using-it-in-the-eu/using-a-blue-badge-in-the-european-union"]," in some circumstances. Check local parking rules."]},{"k":"p","s":["Drink-driving is a serious offence in Czechia. If you are tested and found to have any alcohol or drugs in your system, you may face a fine of up to 50,000 Czech koruna, confiscation of your licence and possible imprisonment. The Czech police can ask any driver to take a breathalyser test on the spot."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["It’s safer to use a major taxi company than to pick one up in the street. Some taxis charge high prices. Always check the rates on the side of the taxi before getting in."]},{"k":"p","s":["Beware of drivers pretending to be taxi services but offering rides in unmarked cars and overcharging for journeys. See information on ",["using Uber at Prague airport","https://www.prg.aero/en/taxi"],", including how to book through the app, at a self-service kiosk or at service counters. Booking through a kiosk is usually slightly more expensive."]},{"k":"hs","s":["Buses and trams"]},{"k":"p","s":["See ",["Prague public transport information and journey planner","https://www.dpp.cz/en"]," in English."]},{"k":"p","s":["Be careful near tram tracks and make sure you look both ways as trams cannot stop quickly. Trams have the right of way on zebra crossings."]},{"k":"p","s":["You may get a fine if you do not cross roads and tram tracks at pedestrian crossings. You can also get a fine if you cross when the pedestrian crossing light is not green."]},{"k":"p","s":["You must validate your ticket in a ticket machine before starting a journey on public transport. You do not need to validate tickets bought from self-service terminals on trams and buses. Officials patrol public transport and will issue an on-the-spot fine of 1,000 Czech koruna (around £35) if you do not hold a validated ticket. If fined, you should get a receipt. If you cannot pay immediately, the police can get involved and the fine could increase to 1,500 koruna."]},{"k":"p","s":["The 30 and 90-minute journey adult tickets for bus, tram and metro are not valid on the Petřín Hill funicular railway in Prague. You need a specific 60-koruna ticket from the vending machines at funicular railway stops, or a 24-hour ticket (or longer)."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/extreme-weather-and-natural-hazards"],"."]},{"k":"p","s":["You can access ",["local forecasts and weather warnings","https://www.chmi.cz/?l=en"]," for Czechia. Follow the instructions of local authorities."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Czechia","https://travelhealthpro.org.uk/country/62/czech-republic#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Czechia","https://travelhealthpro.org.uk/country/62/czech-republic#General_Information"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Czechia"]},{"k":"p","s":["FCDO has a ",["list of medical providers in Czechia","https://www.gov.uk/government/publications/czech-republic-list-of-medical-facilitiespractitioners"]," where some staff will speak English."]},{"k":"hs","s":["Health insurance cards"]},{"k":"p","s":["To get medically necessary state healthcare in Czechia, you need a Global Health Insurance Card (GHIC) or a European Health Insurance Card (EHIC)."]},{"k":"p","s":["The NHS’s ",["getting healthcare abroad webpage","https://www.nhs.uk/using-the-nhs/healthcare-abroad/apply-for-a-free-uk-global-health-insurance-card-ghic/"]," has details about:"]},{"k":"li","s":["how to apply for a GHIC"]},{"k":"li","s":["how to get temporary cover if you lose your card or it does not arrive in time"]},{"k":"li","s":["who qualifies for a new EHIC instead of a GHIC"]},{"k":"li","s":["what treatment counts as medically necessary"]},{"k":"p","s":["A GHIC or EHIC is not an alternative to travel insurance. You may have costs your GHIC or EHIC does not cover, including:"]},{"k":"li","s":["changes to travel and accommodation bookings"]},{"k":"li","s":["additional standard costs for treatment"]},{"k":"li","s":["medical repatriation to the UK"]},{"k":"li","s":["treatment that is ruled non-urgent"]},{"k":"li","s":["private healthcare"]},{"k":"li","s":["private clinics"]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Czechia","https://www.gov.uk/guidance/living-in-the-czech-republic#healthcare-in-the-czech-republic"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Czechia"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Czech%20Republic"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Czech%20Republic"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Czech%20Republic"]," in Czechia"]},{"k":"li","s":["dealing with a ",["death in Czechia","https://www.gov.uk/government/publications/czech-republic-bereavement-packinformation"]]},{"k":"li","s":["being ",["arrested or imprisoned in Czechia","https://www.gov.uk/government/publications/czech-republic-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/czech-republic/british-embassy-prague"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/czech-republic/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Czechia","https://www.gov.uk/government/publications/overseas-business-risk-czech-republic"]," on how to manage political, economic, and business security-related risks."]}],"chars":18681,"change":"Updated information on European Entry-Exit System (EES) (‘Entry requirements’ page)."}};
